const row=$input.first().json;
const parse=x=>typeof x==='string'?JSON.parse(x):x;
const users=parse(row.users)||[];
if(Number(row.product_count)<1||Number(row.product_count)>400)throw new Error('Run needs 1 to 400 pinned products');
const results=[...(parse(row.preclassified_results)||[])];
for(const user of users){
  for(const product of (user.products||[])){
    const rules=parse(product.rules);
    const mandatory=parse(product.mandatory_findings)||[];
    const reasons=[];
    let unresolved=false;
    const required=criterion=>{
      const finding=mandatory.find(f=>f.criterion===criterion);
      if(!finding||finding.status!=='pass')throw new Error('Invalid SQL candidate findings');
      reasons.push(finding);
    };
    if(rules.employment.kind==='required')required('employment_status');
    else{unresolved=true;reasons.push({criterion:'employment_status',status:'unknown',message:'This product employment rule needs confirmation.'});}
    if(rules.age.kind==='required')required('age');
    else{unresolved=true;reasons.push({criterion:'age',status:'unknown',message:'The official source does not establish the age criteria.'});}
    if(rules.monthly_income.kind==='required'&&!rules.monthly_income.location_dependent)required('monthly_income');
    else{unresolved=true;reasons.push({criterion:'monthly_income',status:'unknown',message:'Location-specific income terms cannot be checked from this file.'});}
    const score=rules.credit_score;
    if(score.kind==='required')required('credit_score');
    else if(score.kind==='preferred'){
      const pass=Number(user.credit_score)>=score.min;
      reasons.push({criterion:'credit_score',status:pass?'pass':'review',preferred_minimum:score.min,observed_value:user.credit_score,message:'The source describes this as preferred, not a hard cutoff.'});
      if(!pass)unresolved=true;
    }else{unresolved=true;reasons.push({criterion:'credit_score',status:'unknown',message:'The official source does not establish a score cutoff.'});}
    results.push({user_id:user.user_id,product_id:product.product_id,snapshot_id:product.snapshot_id,decision:unresolved?'review':'eligible',reasons,rule_version:'rules-v2-staged'});
  }
}
if(results.length>400)throw new Error('Page exceeds bounded decision limit');
return [{json:{run_id:row.run_id,cursor_user_id:row.cursor_user_id,results,last_user_id:row.last_user_id,has_more:row.has_more}}];
